	We consider the following minimax optimization problem:
	\begin{equation}\label{problem:1}
		\min \limits_{x\in \mathcal{X}}\max \limits_{y\in \mathcal{Y}}f(x,y),\tag{P}
	\end{equation}
	where $\mathcal{X}\subseteq \mathbb{R}^n$ and $\mathcal{Y}\subseteq \mathbb{R}^m$ are nonempty closed and bounded convex sets, and $f: \mathcal{X} \times \mathcal{Y} \rightarrow \mathbb{R}$
	is a smooth function. This problem has attracted more  attention due to its wide applications in machine learning, signal processing, and many other research fields in recent years.


	{\bfseries Notation}. For vectors, we use $\|\cdot\|$ to denote  the $l_2$-norm. For a function $f(x,y):\mathbb{R}^n\times\mathbb{R}^m\rightarrow \mathbb{R}$, we use $\nabla_{x} f(x,y)$ (or $\nabla_{y} f(x, y)$) to denote the partial gradient of $f$ with respect to the first variable (or the second variable) at point $(x, y)$.
	Let $\mathcal{P}_{\mathcal{X}}$ and $\mathcal{P}_{\mathcal{Y}}$ denote projections onto the sets $\mathcal{X}$ and $\mathcal{Y}$. Finally, we use the notation $\mathcal{O} (\cdot)$ to hide only absolute constants which do not depend on any problem parameter, and $\tilde{\mathcal{O}}(\cdot)$ notation to hide only absolute constants and log factors.


A continuously differentiable function $f(\cdot)$ is called $\theta$-strongly convex if there exists a constant $\theta> 0$ such
that for any $x,y \in \mathcal{X}$,
\begin{equation}
  f(y)\ge f(x)+\langle \nabla f(x),y-x \rangle+\frac{\theta}{2}\|y-x\|^2.\label{scon}
\end{equation}


	Instead of the original function $f(x, y)$, at the $k$-th iteration, AGP uses the gradient of a regularized version of the original function, i.e.,
	\begin{equation}
		f_k (x, y) = f(x, y) + \tfrac{b_{k}}{2} \|x\|^2 -\tfrac{c_{k}}{2}\| y\|^2,\label{sec:2:1}
	\end{equation}
	where $b_{k} \ge 0$ and $c_{k}\ge 0$ are two regularization parameters.
	More specifically, for a given pair $(x_k, y_k) \in \mathcal{X} \times \mathcal{Y}$, AGP
	minimizes a linearized approximation of $f_k(x, y_k)$ plus some regularized terms to update  $x_k$ as follows:
	\begin{align}
		x_{k+1}&={\arg\min}_{x\in \mathcal{X}}\langle  \nabla _x f_k\left( x_k,y_k \right) ,x-x_k \rangle  +\tfrac{\beta_k}{2}\| x-x_k \| ^2\nonumber\\
		&= \mathcal{P}_\mathcal{X} \left( x_k - \tfrac{1}{\beta_k}  \nabla _xf ( x_k,y_k ) - \tfrac{1}{\beta_k} b_{k} x_k \right), \label{sec:2:2}
	\end{align}
	where  $\mathcal{P}_\mathcal{X}$ is the projection operator onto $\mathcal{X}$ and $\beta_k > 0$ denotes
	a stepsize parameter. Similarly, it updates $y_k$ by maximizing a linearized approximation of $f_k(x_{k+1}, y)$ minus some regularized terms, i.e.,
	\begin{align}
		y_{k+1}&={\arg\max}_{y\in \mathcal{Y}}\langle  \nabla _yf_k\left( x_{k+1},y_k \right),y-y_k \rangle  -\tfrac{\gamma_k}{2}\| y-y_k \| ^2\nonumber\\
		&= \mathcal{P}_\mathcal{Y}\left( y_k+\tfrac{1}{\gamma_k} \nabla _y {f}( x_{k+1},y_k ) - \tfrac{1}{\gamma_k} c_k y_k \right),\label{sec:2:3}
	\end{align}
	where  $\mathcal{P}_\mathcal{Y}$ is the projection operator onto  $\mathcal{Y}$ and $\gamma_k >0$ is another stepsize parameter.


	\begin{algorithm}%[H]
		\caption{(An Alternating Gradient Projection (AGP) Algorithm)}
		\label{alg:2.1}
		\begin{algorithmic}
			\STATE{\textbf{Step 1}:Input $x_1,y_1,\beta_1,\gamma_1, b_1, c_1$; Set $k=1$.}
			%    \FOR{$t = 1, ..., T$}
			\STATE{\textbf{Step 2}:Calculate $\beta_k$ and $b_k$, and perform the following update for $x_k$:  	
				\qquad \begin{equation}\label{sec:2:4:agp:upx}
					x_{k+1}=\mathcal{P}_\mathcal{X} \left( x_k - \tfrac{1}{\beta_k}  \nabla _xf ( x_k,y_k ) - \tfrac{1}{\beta_k} b_k x_k \right).
			\end{equation}}		
			\STATE{\textbf{Step 3}:Calculate $\gamma_k$ and $c_k$, and perform the following update for $y_k$:
				\qquad	\begin{equation}\label{sec:2:5:agp:upy}
					y_{k+1}=\mathcal{P}_\mathcal{Y}\left( y_k+\tfrac{1}{\gamma_k} \nabla _y {f}( x_{k+1},y_k ) - \tfrac{1}{\gamma_k} c_k y_k \right).
			\end{equation}}
			\STATE{\textbf{Step 4}:If some stationary condition is satisfied, stop; otherwise, set $k=k+1, $ go to Step 2.}
			%    \ENDFOR
		\end{algorithmic}
	\end{algorithm}


	\begin{defi}\label{sec:2:def1:G}
		At each iteration of Algorithm \ref{alg:2.1}, the stationarity gap for problem \eqref{problem:1} w.r.t. $f(x,y)$ is defined as:
		\begin{equation*}
			\nabla G\left( x_k,y_k \right) :=\left[\begin{array}{c}
				{\beta_k\left(x_k-\operatorname{\mathcal{P}_\mathcal{X}}(x_k-\frac{1}{\beta_k} \nabla_{x} f(x_k ,y_k))\right)} \\

				{\gamma_k\left(y_k-\operatorname{\mathcal{P}_\mathcal{Y}}(y_k+\frac{1}{\gamma_k} \nabla_{y} f(x_k ,y_k))\right)}
			\end{array}\right].
		\end{equation*}
    	We denote $\nabla {G}_k:= \nabla {G}(x_k, y_k)$,
		$(\nabla G_k)_{x}:= \beta_k( x_k-\operatorname{\mathcal{P}_\mathcal{X}}( x_k-\frac{1}{\beta_k}\nabla _{x}f( x_k,y_k)))$,
		and $(\nabla G_k)_{y}:=\gamma_k( y_k-\operatorname{\mathcal{P}_\mathcal{Y}}( y_k+ \frac{1}{\gamma_k} \nabla _{y}f( x_k,y_k )) )$.
		%		\begin{align*}
		%			(\nabla G^r)_{x_i}&:= \beta_i^r\left( x_i^r-\operatorname{Prox_{\mathcal{X}_i}^{\beta_i^r}}\left( x_i^r+ \frac{1}{\beta_i^r} \nabla _{x_i}f\left( x^r,y^r \right) \right) \right),\\
		%			(\nabla G^r)_{y}&:=\rho^r\left( y^r-\operatorname{Prox_{\mathcal{Y}}^{\rho^r}}\left( y^r+ \frac{1}{\rho^r} \nabla _{y}f\left( x^r,y^r \right) \right) \right).
		%		\end{align*}
	\end{defi}

	Note that the widely used metrics for convex-concave minimax problems such as the min-max value or the distance to the set of optimal solutions of the min-max problem are not applicable in nonconvex cases.
	For the latter cases we call $(x_k,y_k)$ an $\varepsilon$-stationary point of $f(x,y)$ if $ \|\nabla G(x_k,y_k)\|\leq \varepsilon$ with $\nabla G(x_k,y_k)$ being defined as in Definition \ref{sec:2:def1:G}, which has been widely used as the optimality measure, e.g., \cite{Lin2020,Lu}. In the absence of constraints, $ \| \nabla G(x_k,y_k)\| \leq \varepsilon$ reduces to the standard condition $ \|\nabla_{x} f(x_k ,y_k)\|\leq \varepsilon $ and $\|\nabla_{y} f(x_k ,y_k)\|\leq \varepsilon$ for unconstrained problems. The vector  $\nabla G(x_k,y_k)$ also refers to gradient mapping at $(x_k,y_k)$, see \cite{Nes2013} for the details. 


	\begin{ass}\label{sec:2:ass1:lip}
		$f\left(x,y\right)$ has Lipschitz continuous gradients, i.e., there exist positive scalars $L_{22}$, $L_{12}$, $L_{11}$, $L_{21}$ such that for any $x,\bar{x}\in \mathcal{X}$, $y, \bar{y}\in \mathcal{Y}$,
		\begin{align*}
			\| \nabla_{x} f\left(x, y\right)-\nabla_{x} f\left(\bar{x}, y\right)\| &\leq L_{11}\|x-\bar{x}\|,\\
			\|\nabla_{x} f\left(x, y\right)-\nabla_{x} f\left(x, \bar{y}\right)\| &\leq L_{21}\|y-\bar{y}\|,\\
			\|\nabla_{y} f\left(x, \bar{y}\right)-\nabla_{y} f\left(x, y\right)\| &\leq L_{22}\|\bar{y}-y\|,\\
			\|\nabla_{y} f\left(x, y\right)-\nabla_{y} f\left(\bar{x}, y\right)\| &\leq L_{12}\|x-\bar{x}\|.
		\end{align*}
		We denote $L:=\max\{L_{11}, L_{22}, L_{12}, L_{21}\}$.
	\end{ass}


\begin{equation}\label{subsec:3.1:1}
		\beta_k=\eta, \gamma_k=\tfrac{1}{\rho}, \ \mbox{and} \ b_k=c_k=0
	\end{equation}

\begin{align}
		x_{k+1}&=\mathcal{P}_\mathcal{X} \left( x_k - \tfrac{1}{\eta}  \nabla _xf ( x_k,y_k )  \right),\label{subsec:3.1:2:x}\\
		y_{k+1}&=\mathcal{P}_\mathcal{Y}\left( y_k+\rho \nabla _y {f}( x_{k+1},y_k ) \right),\label{subsec:3.1:3:y}
	\end{align}

	We are now ready to establish the iteration complexity for the AGP algorithm in the nonconvex-strongly concave setting.
	In particular,
	letting $\nabla G\left( x_k,y_k \right)$ be defined as  in Definition \ref{sec:2:def1:G} and $\varepsilon>0$ be
	a given target accuracy, we provide
	a bound on $T(\varepsilon)$, the first iteration index to achieve an $\varepsilon$-stationary point, i.e., $ \| \nabla G(x_k,y_k)\| \leq \varepsilon$, which is equivalent to
	\begin{equation}\label{subsec:3.1:4:defT}
		T(\varepsilon):=\min\{k \mid \|\nabla G(x_k,y_k)\|\leq \varepsilon \}.
	\end{equation}


\subsection{Strongly Convex-Nonconcave Setting}\label{subsec4}
In this subsection, we analyze the iteration complexity of Algorithm \ref{alg:2.1} for solving strongly convex-nonconcave minimax optimization problems \eqref{problem:1}, i.e., $f(x,y)$ is $\theta$-strongly convex w.r.t. $x$ for any fixed $y\in \mathcal{Y}$,
and nonconcave  w.r.t. $y$ for any given $x\in \mathcal{X}$. Under this setting,   $\forall k\ge 1$, we set
\begin{equation}
\beta_k=\tfrac{1}{\zeta}, \gamma_k=\nu,  b_k=c_k=0,\label{subsec:4.1:1:para}
\end{equation}
in  Algorithm \ref{alg:2.1}, and simplify the update for $x_k$ and $y_k$ as follows:
\begin{align}
	x_{k+1}&=\mathcal{P}_\mathcal{X}\left( x_k- \zeta \nabla _x {f}( x_{k},y_k) \right),\label{subsec:4.1:2:x}\\
	y_{k+1}&=\mathcal{P}_\mathcal{Y} \left(y_k + \tfrac{1}{\nu}  \nabla _yf ( x_{k+1},y_k )  \right)\label{subsec:4.1:3:y}.
\end{align}

