proof.raw_tex:
\begin{lem}\label{lem:2.1}
Suppose that Assumption \ref{sec:2:ass1:lip} holds. Let $\{(x_k,y_k)\}$ be a sequence generated by Algorithm \ref{alg:2.1}. Then we have
\begin{align}
  f\left( x_{k+1},y_k \right) -f\left( x_k,y_k \right) &\le-\left( \beta_k -\tfrac{L_{11}}{2} \right) \lVert x_{k+1}-x_k \rVert ^2-\frac{b_k}{2}\left[\|x_{k+1}\|^2-\|x_k\|^2-\|x_{k+1}-x_k\|^2\right], \label{lem:2.1:1}\\
  f(x_{k+1},y_{k+1})-f( x_{k+1},y_{k})
			&\ge\left( \gamma_k -\tfrac{L_{22}}{2} \right) \lVert y_{k+1}-y_k \rVert ^2+\frac{c_k}{2}\left[\|y_{k+1}\|^2-\|y_k\|^2-\|y_{k+1}-y_k\|^2\right].\label{lem:2.1:2}
\end{align}
\end{lem}

\begin{proof}
  Firstly, by the optimality condition for \eqref{sec:2:4:agp:upx}, we have
		\begin{equation}\label{lem:2.1:3}
			\langle  \nabla _xf\left( x_k,y_k \right) +\beta_k \left( x_{k+1}-x_k \right)+b_kx_k ,x_k-x_{k+1} \rangle  \ge 0.
		\end{equation}
		By Assumption \ref{sec:2:ass1:lip}, the gradient of $f$ is Lipschitz continuous, implying that
		\begin{equation}
			f\left( x_{k+1},y_k \right) -f\left( x_k,y_k \right)\leq \langle  \nabla _xf\left( x_k,y_k \right) ,x_{k+1}-x_k \rangle  +\tfrac{L_{11}}{2}\lVert x_{k+1}-x_k \rVert ^2. \label{lem:2.1:4}
		\end{equation}
		Adding \eqref{lem:2.1:3} and \eqref{lem:2.1:4}, we can easily show that
		\begin{align*}
			f\left( x_{k+1},y_k \right) -f\left( x_k,y_k \right) &\le -\left( \beta_k -\tfrac{L_{11}}{2} \right) \lVert x_{k+1}-x_k \rVert ^2-b_k\langle x_k, x_{k+1}-x_k\rangle\nonumber\\
            &= -\left( \beta_k -\tfrac{L_{11}}{2} \right) \lVert x_{k+1}-x_k \rVert ^2-\frac{b_k}{2}\left[\|x_{k+1}\|^2-\|x_k\|^2-\|x_{k+1}-x_k\|^2\right].
		\end{align*}
This completes the proof of \eqref{lem:2.1:1}. By the optimality condition for \eqref{sec:2:5:agp:upy}, we have
		\begin{equation}\label{lem:2.1:6}
			\langle  \nabla _{y}f( x_{k+1},y_{k})-\gamma_k( y_{k+1}-y_k)-c_ky_k ,y_k-y_{k+1} \rangle  \leq 0.
		\end{equation}
		By  Assumption \ref{sec:2:ass1:lip}, the gradient of $f$ is Lipschitz continuous,  implying that
		\begin{align}\label{lem:2.1:7}
			f(x_{k+1},y_{k+1})-f( x_{k+1},y_{k})
			\ge  \langle \nabla _{y}f(x_{k+1},y_{k}),y_{k+1}
    -y_{k} \rangle -\frac{L_{22}}{2}\| y_{k+1}-y_{k} \|^2.
		\end{align}
			The result \eqref{lem:2.1:2} then follows by adding \eqref{lem:2.1:6} and \eqref{lem:2.1:7}.

\end{proof}

\begin{lem}\label{lem:3.2:blostr:y}
		Suppose that Assumption \ref{sec:2:ass1:lip} holds. Let $\{\left(x_k,y_k\right)\}$ be a sequence generated by Algorithm \ref{alg:2.1}
		with parameter settings in \eqref{subsec:3.1:1}. If $\eta > L_{11}$, then we have
		\begin{align}\label{lem:3.2:1}
			&f( x_{k+1},y_{k+1}) -f\left( x_k,y_k \right)  \nonumber \\
			\leq& -\left(\tfrac{\eta}{2}-\tfrac{L_{12}^{2}\rho}{2}\right)\| x_{k+1}-x_{k} \| ^2-\left(\tfrac{\mu}{2}-\tfrac{1}{\rho}\right)\| y_{k+1}-y_k \|^2\nonumber \\
			&-\left(\mu-\tfrac{1}{2\rho}-\tfrac{\rho L_{22}^2}{2}\right)\|y_k-y_{k-1} \|^2.
		\end{align}
	\end{lem}

\begin{proof}
		The optimality condition for $y_k$ in \eqref{subsec:3.1:3:y} implies that $\forall y\in \mathcal{Y}$ and $\forall k\geq 1$,
		\begin{equation}\label{lem:3.2:2}
			\langle \nabla _yf(x_{k+1},y_k)-\frac{1}{\rho}(y_{k+1}-y_k),y-y_{k+1} \rangle \le 0.
		\end{equation}
		By choosing $y=y_k$ in \eqref{lem:3.2:2}, we have
		\begin{equation}\label{lem:3.2:3}
			\langle \nabla _yf(x_{k+1},y_k)-\frac{1}{\rho}(y_{k+1}-y_k),y_k-y_{k+1} \rangle \le 0.
		\end{equation}
		On the other hand, by replacing $k$ with $k-1$ and choosing $y=y_{k+1}$ in \eqref{lem:3.2:2}, we obtain
		\begin{equation}\label{lem:3.2:4}
			\langle \nabla _yf(x_{k},y_{k-1})-\frac{1}{\rho}(y_k-y_{k-1}),y_{k+1}-y_k \rangle \le 0,
		\end{equation}
		which, in view of the fact that $f\left( x,y  \right)$ is $\mu $-strongly concave w.r.t. $y$ for any given $x\in \mathcal{X}$,
		then implies that
		\begin{align}\label{lem:3.2:5}
			&f( x_{k+1},y_{k+1}) -f( x_{k+1},y_k ) \nonumber\\
			\leq &  \langle  \nabla _yf( x_{k+1},y_k ),y_{k+1}-y_k\rangle  -\frac{\mu}{2}\| y_{k+1}-y_k \|^2\  \nonumber\\
			\leq &\langle  \nabla _yf( x_{k+1},y_k ) -\nabla _yf( x_k,y_{k-1}) ,y_{k+1}-y_k \rangle   \nonumber\\
			& +\frac{1}{\rho}\langle  y_k-y_{k-1},y_{k+1}-y_k\rangle  -\frac{\mu}{2}\| y_{k+1}-y_k \|^2.
		\end{align}
		Denoting $v_{k+1}:=\left(y_{k+1}-y_k\right)-\left(y_k-y_{k-1}\right)$, we can write the first inner product term in the r.h.s.
		of \eqref{lem:3.2:5} as
		\begin{align}\label{lem:3.2:6}
			&\langle  \nabla _y f ( x_{k+1},y_k ) -\nabla _y f ( x_k,y_{k-1}) ,y_{k+1}-y_k \rangle  \nonumber\\
			=&\langle  \nabla _y f ( x_{k+1},y_k ) -\nabla _y f \left( x_k,y_{k} \right) ,y_{k+1}-y_k \rangle  \nonumber\\
			& + \langle  \nabla _y f \left( x_k,y_{k} \right) -\nabla _y f ( x_k,y_{k-1}) ,v_{k+1} \rangle  \nonumber\\
			&+\langle  \nabla _y f \left( x_k,y_{k}\right) -\nabla _y f ( x_k,y_{k-1}) ,y_k-y_{k-1} \rangle .
		\end{align}
		Next, we estimate the three terms in the right hand side of \eqref{lem:3.2:6} respectively.
		By Assumption \ref{sec:2:ass1:lip} and the Cauchy-Schwarz inequality, we can bound the first two terms according to
		\begin{align}\label{lem:3.2:7}
			&\langle  \nabla _yf( x_{k+1},y_k ) -\nabla _yf\left( x_k,y_{k} \right) ,y_{k+1}-y_k \rangle  \nonumber\\
			\leq &\frac{L_{12}^{2}\rho}{2}\| x_{k+1}-x_k \|^2+\frac{1}{2\rho}\| y_{k+1}-y_k \|^2,
		\end{align}
		and
		\begin{align}\label{lem:3.2:8}
			&\langle  \nabla _yf\left(  x_k,y_{k} \right) -\nabla _yf( x_k,y_{k-1}) ,v_{k+1} \rangle  \leq \frac{\rho L_{22}^{2}}{2}\|y_k-y_{k-1} \|^2+\frac{1}{2\rho}\|v_{k+1} \|^2.
		\end{align}
		For the third term, by $\mu $-strongly-concavity  of $f$ with respect to $y$,
		\begin{align}\label{lem:3.2:9}
			\quad \langle  \nabla _yf\left( x_k,y_{k} \right) -\nabla _yf( x_k,y_{k-1}) ,y_k-y_{k-1} \rangle  \le -\mu \| y_k-y_{k-1} \|^2 .
		\end{align}
		Moreover, it can be easily checked that
		\begin{align}\label{lem:3.2:10:3points}
			&\langle  y_k-y_{k-1},y_{k+1}-y_k \rangle =\frac{1}{2}\| y_k-y_{k-1} \|^2+\frac{1}{2}\| y_{k+1}-y_k \|^2-\frac{1}{2}\| v_{k+1} \|^2.
		\end{align}
		Plugging \eqref{lem:3.2:6}-\eqref{lem:3.2:10:3points} into \eqref{lem:3.2:5} and rearranging the terms, we conclude that
		\begin{align}\label{lem:3.2:11}
			&f( x_{k+1},y_{k+1}) -f( x_{k+1},y_{k})  \nonumber \\
			\leq& \frac{L_{12}^{2}\rho}{2}\| x_{k+1}-x_k \|^2-(\mu-\frac{1}{2\rho}-\frac{\rho L_{22}^2}{2})\| y_k-y_{k-1}\|^2\nonumber\\
			&-(\frac{\mu}{2}-\frac{1}{\rho})\|y_{k+1}-y_k \|^2.
		\end{align}
By setting $\beta_k=\eta$, $b_k=0$ in \eqref{lem:2.1:1} of Lemma \ref{lem:2.1}  and the assumption $\eta > L_{11}$, we have
		\begin{equation}\label{lem:3.1:1}
			f(x_{k+1},y_{k})-f(x_{k},y_k)\le -\frac{\eta}{2}\| x_{k+1}-x_k \|^2.
		\end{equation}
The proof is completed by combining \eqref{lem:3.2:11} with \eqref{lem:3.1:1}.
	\end{proof}

\begin{lem}\label{lem:4.2}
	Suppose that Assumption \ref{sec:2:ass1:lip} holds. Let $\{\left(x_{k},y_{k}\right)\}$ be a sequence generated by Algorithm \ref{alg:2.1}
	with parameter settings in \eqref{subsec:4.1:1:para}. If $\nu > L_{22}$, then we have
	\begin{align}\label{lem:4.2:1:conclu}
		&f( x_{k+1},y_{k+1}) -f( x_{k},y_{k})  \nonumber \\
		\geq& \frac{\nu}{2}\| y_{k+1}-y_{k} \| ^2-\frac{L_{21}^{2}\zeta}{2}\| y_{k}-y_{k-1} \|^2+(\theta-\frac{1}{2\zeta}-\frac{\zeta L_{11}^2}{2})\| x_{k}-x_{k-1}\|^2\nonumber\\
		&+ (\frac{\theta}{2}-\frac{1}{\zeta})\|x_{k+1}-x_{k} \|^2.
	\end{align}
\end{lem}

\begin{proof}
	Similar to \eqref{lem:3.2:2}-\eqref{lem:3.2:4} in the proof of Lemma \ref{lem:3.2:blostr:y}, by the optimality condition for $x_k$ in \eqref{subsec:4.1:2:x} implies that $\forall x\in \mathcal{X}$ and $\forall k\geq 1$,
	\begin{align}
		\langle \nabla _xf(x_{k},y_{k})+\frac{1}{\zeta}(x_{k+1}-x_{k}),x-x_{k+1} \rangle &\ge 0,\label{lem:4.2:2:opty}\\
		\langle \nabla _xf(x_{k},y_{k})+\frac{1}{\zeta}(x_{k+1}-x_{k}) ,x_{k}-x_{k+1} \rangle &\ge 0,\label{lem:4.2:3:nopty}\\
		\langle \nabla _xf(x_{k-1},y_{k-1})+\frac{1}{\zeta}(x_{k}-x_{k-1}),x_{k+1}-x_{k} \rangle &\ge 0,\label{lem:4.2:4:opty:k}
	\end{align}
which, in view of the fact that $f\left( x,y  \right)$ is $\theta $-strongly convex w.r.t. $x$ for any given $y\in \mathcal{Y}$,
	then implies that
	\begin{align}\label{lem:4.2:5}
		&f( x_{k+1},y_{k}) -f( x_{k},y_{k} ) \nonumber\\
		\geq &  \langle  \nabla _xf( x_{k},y_{k} ),x_{k+1}-x_{k}\rangle  +\frac{\theta}{2}\| x_{k+1}-x_{k} \|^2\  \nonumber\\
		\geq &\langle  \nabla _xf( x_{k},y_{k} ) -\nabla _xf( x_{k-1},y_{k-1}) ,x_{k+1}-x_{k} \rangle  \nonumber\\
		& -\frac{1}{\zeta}\langle  x_{k}-x_{k-1},x_{k+1}-x_{k} \rangle +\frac{\theta}{2}\| x_{k+1}-x_{k} \|^2.
	\end{align}
	Denoting $m_{k+1}:=\left(x_{k+1}-x_k\right)-\left(x_k-x_{k-1}\right)$, by Assumption \ref{sec:2:ass1:lip}, the Cauchy-Schwarz inequality and
	the $\theta $-strongly convexity  of $f$ w.r.t. $x$, we can estimate the first inner product term in the r.h.s.
	of \eqref{lem:4.2:5} as
	\begin{align}
		&\langle  \nabla _x f ( x_{k},y_{k} ) -\nabla _x f ( x_{k-1},y_{k-1}) ,x_{k+1}-x_{k} \rangle  \nonumber\\
		=&\langle  \nabla _x f ( x_{k},y_{k} ) -\nabla _x f \left( x_{k},y_{k-1} \right) ,x_{k+1}-x_{k} \rangle  \nonumber\\
		& + \langle  \nabla _x f \left( x_{k},y_{k-1} \right) -\nabla _x f ( x_{k-1},y_{k-1}) ,m_{k+1} \rangle  \nonumber\\
		&+\langle  \nabla _x f \left( x_{k},y_{k-1}\right) -\nabla _x f ( x_{k-1},y_{k-1}) ,x_{k}-x_{k-1} \rangle \label{lem:4.2:6}\\
	\geq &-\frac{L_{21}^{2}\zeta}{2}\| y_{k}-y_{k-1} \|^2-\frac{1}{2\zeta}\| x_{k+1}-x_k \|^2-\frac{\zeta L_{11}^{2}}{2}\|x_k-x_{k-1} \|^2\nonumber\\
	&-\frac{1}{2\zeta}\|m_{k+1} \|^2 +	\theta \| x_k-x_{k-1} \|^2.\label{lem:4.2:7}
	\end{align}
	Moreover, it can be easily checked that
\begin{align}\label{lem:4.2:8:3points}
		&\langle  x_k-x_{k-1},x_{k+1}-x_k \rangle =\frac{1}{2}\| x_k-x_{k-1} \|^2+\frac{1}{2}\| x_{k+1}-x_k \|^2-\frac{1}{2}\| m_{k+1} \|^2.
	\end{align}
	Plugging \eqref{lem:4.2:7} and \eqref{lem:4.2:8:3points} into \eqref{lem:4.2:5} and rearranging the terms, we conclude that
	\begin{align}\label{lem:4.2:9}
	f( x_{k+1},y_{k}) -f( x_{k},y_{k})	\geq& -\frac{L_{21}^{2}\zeta}{2}\| y_{k}-y_{k-1} \|^2+(\theta-\frac{1}{2\zeta}-\frac{\zeta L_{11}^2}{2})\| x_{k}-x_{k-1}\|^2\nonumber\\
		&+ (\frac{\theta}{2}-\frac{1}{\zeta})\|x_{k+1}-x_{k} \|^2.
	\end{align}
By setting $\gamma_k=\nu$, $c_k=0$ in \eqref{lem:2.1:2} of Lemma \ref{lem:2.1}  and the assumption $\nu > L_{22}$, we have
		\begin{equation}\label{lem:4.1:1:conclu}
			f( x_{k+1},y_{k+1}) -f( x_{k+1},y_k )\ge \frac{\nu}{2}\| y_{k+1}-y_k \|^2.
		\end{equation}
	The proof is completed by combining \eqref{lem:4.2:9} with \eqref{lem:4.1:1:conclu}.
\end{proof}

\begin{lem}\label{lem:4.3}
	Suppose that Assumption \ref{sec:2:ass1:lip} holds. Let $\{\left(x_k,y_k\right)\}$ be a sequence generated by Algorithm \ref{alg:2.1}
	with parameter settings in \eqref{subsec:4.1:1:para}. Denote
	$$\hat{f}_{k+1}:=f\left( x_{k+1},y_{k+1} \right),\ \hat{S}_{k+1}:=-\frac{2}{\zeta^2\theta}\lVert x_{k+1}-x_k \rVert^2,$$
	$$\hat{F}_{k+1}:=\hat{f}_{k+1}+\hat{S}_{k+1}+ (\theta+\frac{7}{2\zeta}-\frac{\zeta L_{11}^2}{2}-\frac{2L_{11}^2}{\theta})\lVert x_{k+1}-x_{k} \rVert^2-(\frac{L_{21}^2\zeta}{2}+\frac{2L_{21}^2}{\theta^2\zeta})\|y_{k+1}-y_k\|^2.$$
	If $\nu>L_{22}$,
%	\begin{equation}\label{lem:4.3:1}
%, \nu>L_{21}^2\zeta+\frac{4L_{21}^2}{\zeta \theta^2},~\zeta\leq \frac{\theta}{4L_{11}^2},
%	\end{equation}
	then $\forall k \geq 1$,
	\begin{align}\label{lem:4.3:2:conclus}
		\hat{F}_{k+1}-\hat{F}_k\geq& \left(\frac{\nu}{2}-\frac{\zeta L_{21}^2}{2}-\frac{2L_{21}^2}{\zeta \theta^2}\right)\lVert y_{k+1}-y_k \rVert ^2\nonumber\\
		& +\left(\frac{3\theta-\zeta L_{11}^2}{2}+\frac{\theta-4\zeta L_{11}^2}{2\zeta\theta}\right)\lVert x_{k+1}-x_k \rVert ^2.
	\end{align}
\end{lem}

\begin{proof}
First by \eqref{lem:4.2:3:nopty} and \eqref{lem:4.2:4:opty:k}, we have
	\begin{align}\label{lem:4.3:3}
		\frac{1}{\zeta}\langle m_{k+1}, x_k -x_{k+1} \rangle
		\ge \langle \nabla _xf( x_k,y_k ) -\nabla _xf\left( x_{k-1},y_{k-1} \right),x_{k+1}-x_k \rangle,
	\end{align}
which together with \eqref{lem:4.2:6} then imply that
%	\eqref{lem:4.3:3} then implies that
	\begin{align}
		\frac{1}{\zeta}\langle m_{k+1},x_k-x_{k+1}  \rangle  \geq&\langle  \nabla _xf( x_{k},y_{k} ) -\nabla _xf\left( x_{k},y_{k-1} \right) ,x_{k+1}-x_{k} \rangle  \nonumber\\
		& + \langle  \nabla _xf\left( x_{k},y_{k-1} \right) -\nabla _xf\left( x_{k-1},y_{k-1} \right) ,m_{k+1} \rangle  \nonumber\\
		&+\langle  \nabla _xf\left( x_k,y_{k-1} \right) -\nabla _xf\left( x_{k-1},y_{k-1} \right) ,x_{k}-x_{k-1} \rangle \label{lem:4.3:4}\\
		\geq& -\frac{L_{21}^{2}}{2 \theta}\|y_{k}-y_{k-1} \|^2-\frac{\theta}{2}\|x_{k+1}-x_{k} \|^2-\frac{\zeta L_{11}^2}{2}\|x_{k}-x_{k-1} \|^2\nonumber\\
		&-\frac{1}{2\zeta}\| m_{k+1}\|^2+\theta\|x_{k}-x_{k-1} \|^2,\label{lem:4.3:5}
	\end{align}
where the second inequality is similar to the proof of \eqref{lem:4.2:7} except that for the first term in the r.h.s., we use $\langle  \nabla _xf( x_{k},y_{k} ) -\nabla _xf\left( x_{k},y_{k-1} \right) ,x_{k+1}-x_{k} \rangle \geq -\frac{L_{21}^{2}}{2 \theta}\|y_{k}-y_{k-1} \|^2-\frac{\theta}{2}\|x_{k+1}-x_k \|^2$. By using the identity $\frac{1}{\zeta}\langle m_{k+1},x_{k}-x_{k+1} \rangle  =\frac{1}{2\zeta}\|x_{k}-x_{k-1}\|^2- \frac{1}{2\zeta}\|x_{k+1}-x_{k}\|^2-\frac{1}{2\zeta}\| m_{k+1}\| ^2$, we conclude from \eqref{lem:4.3:5} that
	\begin{align}\label{lem:4.3:6}
		&\frac{1}{2\zeta}\|x_{k}-x_{k-1}\|^2- \frac{1}{2\zeta}\|x_{k+1}-x_{k}\|^2-\frac{1}{2\zeta}\| m_{k+1}\| ^2\nonumber\\
		\geq& -\frac{L_{21}^{2}}{2 \theta}\|y_{k}-y_{k-1} \|^2-\frac{\theta}{2}\|x_{k+1}-x_k \|^2-\frac{\zeta L_{11}^2}{2}\|x_{k}-x_{k-1} \|^2\nonumber\\
		&-\frac{1}{2\zeta}\| m_{k+1}\|^2+\theta\|x_{k}-x_{k-1} \|^2.
	\end{align}
	Rearranging the terms of \eqref{lem:4.3:6}, we have
	\begin{align}\label{lem:4.3:7}
		&\frac{1}{2\zeta}\|x_{k}-x_{k-1}\|^2- \frac{1}{2\zeta}\|x_{k+1}-x_{k}\|^2\nonumber\\
		\geq& -\frac{L_{21}^{2}}{2 \theta}\|y_{k}-y_{k-1} \|^2-\frac{\theta}{2}\|x_{k+1}-x_{k} \|^2+\left(\theta-\frac{\zeta L_{11}^2}{2}\right)\|x_{k}-x_{k-1} \|^2.
	\end{align}
	Multiplying $\frac{4}{\zeta\theta}$ on both sides of \eqref{lem:4.3:7} and using the definition of $\hat{S}_{k+1}$, we obtain
	\begin{align*}
		\hat{S}_{k+1}-\hat{S}_k \geq & -\frac{2L_{21}^{2}}{\theta^2\zeta}\| y_{k}-y_{k-1}\|^2-\frac{2}{\zeta}\| x_{k+1}-x_k \|^2+\left(\frac{4}{\zeta}-\frac{2 L_{11}^2}{\theta}\right)\|x_{k}-x_{k-1} \|^2.
	\end{align*}
	The proof is completed by \eqref{lem:4.2:1:conclu} in Lemma \ref{lem:4.2} and the definition of $\hat{F}_k$.
\end{proof}

\begin{proof}
	By \eqref{subsec:4.1:2:x}, we immediately obtain
	\begin{equation}
		\|(\nabla G_k)_{x} \|\leq\frac{1}{\zeta}\| x_{k+1}-x_{k} \|.\label{thm:4.1:1:gx}
	\end{equation}
	On the other hand, similar to the proof of \eqref{thm:3.1:2:gy},  by \eqref{subsec:4.1:3:y} and the triangle inequality, and the nonexpansiveness of the projection operator $\operatorname{ \mathcal{P}_\mathcal{Y}}$, we conclude that
	\begin{align}\label{thm:4.1:2:gy}
		\| (\nabla G_k)_{y} \|\le& \nu\| y_{k+1}-y_k \|+L_{12}\|x_{k+1}-x_{k} \|.
			\end{align}
%		\leq&\nu\|\operatorname{ Prox_{\mathcal{Y}_j}^{\nu}}\left( y_j^r+\frac{1}{\nu} \nabla _{y_j}f\left( x^{r+1} ,w_j^{r+1} \right) \right)-\operatorname{ Prox_{\mathcal{Y}_j}^{\nu}}\left( y_j^r+ \frac{1}{\nu} \nabla _{y_j}f\left( x^r,y^r \right) \right) \|\nonumber\\
%		&+\nu\| y_j^{r+1}-y_j^r \|\nonumber\\
%		\leq& \nu\| y_j^{r+1}-y_j^r \| +\|\nabla _{y_j}f\left( x^{r+1} ,w_j^{r+1} \right)-\nabla _{y_j}f\left( x^r,y^r \right) \|\nonumber\\
%		\leq & \nu\| y_j^{r+1}-y_j^r \| +\|\nabla _{y_j}f\left( x^{r+1} ,w_j^{r+1} \right)-\nabla _{y_j}f\left( x^r,w_j^{r+1} \right) \|\nonumber\\
%		& +\|\nabla _{y_j}f\left( x^r ,w_j^{r+1} \right)-\nabla _{y_j}f\left( x^r,y^r \right) \|\nonumber\\
%		\le& \nu\| y_j^{r+1}-y_j^r \|+L_{12}\|x^{r+1}-x^r \|+L_{22}\|w_j^{r+1}-y^r \|\nonumber\\
%	where the second inequality holds by the nonexpansiveness of the proximal operator $\operatorname{ Prox_{\mathcal{Y}_j}^{\nu}}$, the last inequality holds since that $\| y_i^{r+1}-y_i^r \|\le\| y^{r+1}-y^r \|$ and $\|w_j^{r+1}-y^r \|\le\| y^{r+1}-y^r \|$ by the definition of $y_j$ and $w_j^{r+1}$.
	By combining \eqref{thm:4.1:1:gx} and \eqref{thm:4.1:2:gy}, and using the Cauchy-Schwarz inequality, we obtain
	\begin{align}\label{thm:4.1:3:g}
		\| \nabla G_k \|^2
		\leq 2\nu^2\| y_{k+1}-y_{k} \|^2+\left( \frac{1}{\zeta ^2}+2L_{12}^{2} \right)\|x_{k+1}-x_{k} \|^2.
	\end{align}
	Observing that $\hat{d}_1 > 0$. Multiplying both sides of \eqref{thm:4.1:3:g} by $\hat{d}_1$, and using \eqref{lem:4.3:2:conclus} in Lemma \ref{lem:4.3},
	we have
	\begin{align}\label{thm:4.1:4:d1}
		\hat{d}_1\|\nabla G_k \|^2\le \hat{F}_{k+1}-\hat{F}_k.
	\end{align}
	Summing up the above inequalities from $k=1$ to $k=T(\varepsilon)$, we obtain
	\begin{align}\label{thm:4.1:5}
		\sum_{k=1}^{T\left( \varepsilon \right)}{\hat{d}_1\|\nabla G_k \| ^2}\le \hat{F}_{T\left( \varepsilon \right)+1}-\hat{F}_1.
	\end{align}
	Note that by the definition of $\hat{F}_{k+1}$ in Lemma \ref{lem:4.3}, we have
	\begin{align*}
		\hat{F}_{T\left( \varepsilon \right)+1}&\le
		\hat{f}_{T\left( \varepsilon \right)+1}+(\theta+\frac{7}{2\zeta}-\frac{\zeta L_{11}^2}{2}-\frac{2L_{11}^2}{\theta})\|x_{T\left( \varepsilon \right)+1}-x_{T\left( \varepsilon \right)} \|^2\\
		&\le \bar{f}+(\theta+\frac{7}{2\zeta}-\frac{\zeta L_{11}^2}{2}-\frac{2L_{11}^2}{\theta})\sigma_x^2 = \bar{F},
	\end{align*}
	where the last inequality follows from the definitions of $\bar{f}$ and  $\sigma _x$, and $\theta+\frac{7}{2\zeta}-\frac{\zeta L_{11}^2}{2}-\frac{2L_{11}^2}{\theta} \ge 0 $ due to
	the selection of $\zeta$.
	We then conclude from \eqref{thm:4.1:5} that $\sum_{k=1}^{T\left( \varepsilon \right)}{\hat{d}_1\| \nabla G_k \|^2}\le \bar{F}-\hat{F}_1$ which, in view of the definition of $T(\varepsilon)$, implies that $\varepsilon ^2\le (\bar{F}-\hat{F}_1)/(T( \varepsilon )\cdot \hat{d}_1)$
	or equivalently, $T\left( \varepsilon \right) \le (\bar{F}-\hat{F}_1)/(\hat{d}_1\varepsilon ^2)$.
\end{proof}

