We consider the following minimax optimization problem:
\begin{equation}\label{problem:1}
	\min \limits_{x\in \mathcal{X}}\max \limits_{y\in \mathcal{Y}}f(x,y),\tag{P}
\end{equation}
where $\mathcal{X}\subseteq \mathbb{R}^n$ and $\mathcal{Y}\subseteq \mathbb{R}^m$ are nonempty closed and bounded convex sets, and $f: \mathcal{X} \times \mathcal{Y} \rightarrow \mathbb{R}$
is a smooth function. This problem has attracted more  attention due to its wide applications in machine learning, signal processing, and many other research fields in recent years.

A continuously differentiable function $f(\cdot)$ is called $\theta$-strongly convex if there exists a constant $\theta> 0$ such
that for any $x,y \in \mathcal{X}$,
\begin{equation}
  f(y)\ge f(x)+\langle \nabla f(x),y-x \rangle+\frac{\theta}{2}\|y-x\|^2.\label{scon}
\end{equation}

Instead of the original function $f(x, y)$, at the $k$-th iteration, AGP uses the gradient of a regularized version of the original function, i.e.,
\begin{equation}
	f_k (x, y) = f(x, y) + \tfrac{b_{k}}{2} \|x\|^2 -\tfrac{c_{k}}{2}\| y\|^2,\label{sec:2:1}
\end{equation}
where $b_{k} \ge 0$ and $c_{k}\ge 0$ are two regularization parameters.

More specifically, for a given pair $(x_k, y_k) \in \mathcal{X} \times \mathcal{Y}$, AGP
minimizes a linearized approximation of $f_k(x, y_k)$ plus some regularized terms to update  $x_k$ as follows:
\begin{align}
	x_{k+1}&={\arg\min}_{x\in \mathcal{X}}\langle  \nabla _x f_k\left( x_k,y_k \right) ,x-x_k \rangle  +\tfrac{\beta_k}{2}\| x-x_k \| ^2\nonumber\\
	&= \mathcal{P}_\mathcal{X} \left( x_k - \tfrac{1}{\beta_k}  \nabla _xf ( x_k,y_k ) - \tfrac{1}{\beta_k} b_{k} x_k \right), \label{sec:2:2}
\end{align}
where  $\mathcal{P}_\mathcal{X}$ is the projection operator onto $\mathcal{X}$ and $\beta_k > 0$ denotes

a stepsize parameter. Similarly, it updates $y_k$ by maximizing a linearized approximation of $f_k(x_{k+1}, y)$ minus some regularized terms, i.e.,
\begin{align}
	y_{k+1}&={\arg\max}_{y\in \mathcal{Y}}\langle  \nabla _yf_k\left( x_{k+1},y_k \right),y-y_k \rangle  -\tfrac{\gamma_k}{2}\| y-y_k \| ^2\nonumber\\
	&= \mathcal{P}_\mathcal{Y}\left( y_k+\tfrac{1}{\gamma_k} \nabla _y {f}( x_{k+1},y_k ) - \tfrac{1}{\gamma_k} c_k y_k \right),\label{sec:2:3}
\end{align}
where  $\mathcal{P}_\mathcal{Y}$ is the projection operator onto  $\mathcal{Y}$ and $\gamma_k >0$ is another stepsize parameter.

\begin{algorithm}%[H]
	\caption{(An Alternating Gradient Projection (AGP) Algorithm)}
	\label{alg:2.1}
	\begin{algorithmic}
		\STATE{\textbf{Step 1}:Input $x_1,y_1,\beta_1,\gamma_1, b_1, c_1$; Set $k=1$.}
		%    \FOR{$t = 1, ..., T$}
		\STATE{\textbf{Step 2}:Calculate $\beta_k$ and $b_k$, and perform the following update for $x_k$:  	
			\qquad \begin{equation}\label{sec:2:4:agp:upx}
				x_{k+1}=\mathcal{P}_\mathcal{X} \left( x_k - \tfrac{1}{\beta_k}  \nabla _xf ( x_k,y_k ) - \tfrac{1}{\beta_k} b_k x_k \right).
		\end{equation}}		
		\STATE{\textbf{Step 3}:Calculate $\gamma_k$ and $c_k$, and perform the following update for $y_k$:
			\qquad	\begin{equation}\label{sec:2:5:agp:upy}
				y_{k+1}=\mathcal{P}_\mathcal{Y}\left( y_k+\tfrac{1}{\gamma_k} \nabla _y {f}( x_{k+1},y_k ) - \tfrac{1}{\gamma_k} c_k y_k \right).
		\end{equation}}
		\STATE{\textbf{Step 4}:If some stationary condition is satisfied, stop; otherwise, set $k=k+1, $ go to Step 2.}
		%    \ENDFOR
	\end{algorithmic}
\end{algorithm}

	\begin{defi}\label{sec:2:def1:G}
		At each iteration of Algorithm \ref{alg:2.1}, the stationarity gap for problem \eqref{problem:1} w.r.t. $f(x,y)$ is defined as:
		\begin{equation*}
			\nabla G\left( x_k,y_k \right) :=\left[\begin{array}{c}
				{\beta_k\left(x_k-\operatorname{\mathcal{P}_\mathcal{X}}(x_k-\frac{1}{\beta_k} \nabla_{x} f(x_k ,y_k))\right)} \\

				{\gamma_k\left(y_k-\operatorname{\mathcal{P}_\mathcal{Y}}(y_k+\frac{1}{\gamma_k} \nabla_{y} f(x_k ,y_k))\right)}
			\end{array}\right].
		\end{equation*}
    	We denote $\nabla {G}_k:= \nabla {G}(x_k, y_k)$,
		$(\nabla G_k)_{x}:= \beta_k( x_k-\operatorname{\mathcal{P}_\mathcal{X}}( x_k-\frac{1}{\beta_k}\nabla _{x}f( x_k,y_k)))$,
		and $(\nabla G_k)_{y}:=\gamma_k( y_k-\operatorname{\mathcal{P}_\mathcal{Y}}( y_k+ \frac{1}{\gamma_k} \nabla _{y}f( x_k,y_k )) )$.
