			\leq &  \langle  \nabla _yf( x_{k+1},y_k ),y_{k+1}-y_k\rangle  -\frac{\mu}{2}\| y_{k+1}-y_k \|^2\  \nonumber\\
			\leq &\langle  \nabla _yf( x_{k+1},y_k ) -\nabla _yf( x_k,y_{k-1}) ,y_{k+1}-y_k \rangle   \nonumber\\
			& +\frac{1}{\rho}\langle  y_k-y_{k-1},y_{k+1}-y_k\rangle  -\frac{\mu}{2}\| y_{k+1}-y_k \|^2.
		\end{align}
