			=&\langle  \nabla _y f ( x_{k+1},y_k ) -\nabla _y f \left( x_k,y_{k} \right) ,y_{k+1}-y_k \rangle  \nonumber\\
			& + \langle  \nabla _y f \left( x_k,y_{k} \right) -\nabla _y f ( x_k,y_{k-1}) ,v_{k+1} \rangle  \nonumber\\
			&+\langle  \nabla _y f \left( x_k,y_{k}\right) -\nabla _y f ( x_k,y_{k-1}) ,y_k-y_{k-1} \rangle .
		\end{align}
		Next, we estimate the three terms in the right hand side of \eqref{lem:3.2:6} respectively.
