			&\langle  \nabla _yf( x_{k+1},y_k ) -\nabla _yf\left( x_k,y_{k} \right) ,y_{k+1}-y_k \rangle  \nonumber\\
			\leq &\frac{L_{12}^{2}\rho}{2}\| x_{k+1}-x_k \|^2+\frac{1}{2\rho}\| y_{k+1}-y_k \|^2,
		\end{align}
		and
		\begin{align}\label{lem:3.2:8}
			&\langle  \nabla _yf\left(  x_k,y_{k} \right) -\nabla _yf( x_k,y_{k-1}) ,v_{k+1} \rangle  \leq \frac{\rho L_{22}^{2}}{2}\|y_k-y_{k-1} \|^2+\frac{1}{2\rho}\|v_{k+1} \|^2.
		\end{align}
		For the third term, by $\mu $-strongly-concavity  of $f$ with respect to $y$,
		\begin{align}\label{lem:3.2:9}
			\quad \langle  \nabla _yf\left( x_k,y_{k} \right) -\nabla _yf( x_k,y_{k-1}) ,y_k-y_{k-1} \rangle  \le -\mu \| y_k-y_{k-1} \|^2 .
		\end{align}
		Moreover, it can be easily checked that
		\begin{align}\label{lem:3.2:10:3points}
			&\langle  y_k-y_{k-1},y_{k+1}-y_k \rangle =\frac{1}{2}\| y_k-y_{k-1} \|^2+\frac{1}{2}\| y_{k+1}-y_k \|^2-\frac{1}{2}\| v_{k+1} \|^2.
		\end{align}
		Plugging \eqref{lem:3.2:6}-\eqref{lem:3.2:10:3points} into \eqref{lem:3.2:5} and rearranging the terms, we conclude that
		\begin{align}\label{lem:3.2:11}
			&f( x_{k+1},y_{k+1}) -f( x_{k+1},y_{k})  \nonumber \\
			\leq& \frac{L_{12}^{2}\rho}{2}\| x_{k+1}-x_k \|^2-(\mu-\frac{1}{2\rho}-\frac{\rho L_{22}^2}{2})\| y_k-y_{k-1}\|^2\nonumber\\
			&-(\frac{\mu}{2}-\frac{1}{\rho})\|y_{k+1}-y_k \|^2.
		\end{align}
By setting $\beta_k=\eta$, $b_k=0$ in \eqref{lem:2.1:1} of Lemma \ref{lem:2.1}  and the assumption $\eta > L_{11}$, we have
		\begin{equation}\label{lem:3.1:1}
			f(x_{k+1},y_{k})-f(x_{k},y_k)\le -\frac{\eta}{2}\| x_{k+1}-x_k \|^2.
		\end{equation}
The proof is completed by combining \eqref{lem:3.2:11} with \eqref{lem:3.1:1}.
	\end{proof}

\begin{proof}
		The optimality condition for $y_k$ in \eqref{subsec:3.1:3:y} implies that $\forall y\in \mathcal{Y}$ and $\forall k\geq 1$,
		\begin{equation}\label{lem:3.2:2}
			\langle \nabla _yf(x_{k+1},y_k)-\frac{1}{\rho}(y_{k+1}-y_k),y-y_{k+1} \rangle \le 0.
		\end{equation}
		By choosing $y=y_k$ in \eqref{lem:3.2:2}, we have
		\begin{equation}\label{lem:3.2:3}
			\langle \nabla _yf(x_{k+1},y_k)-\frac{1}{\rho}(y_{k+1}-y_k),y_k-y_{k+1} \rangle \le 0.
		\end{equation}

On the other hand, by replacing $k$ with $k-1$ and choosing $y=y_{k+1}$ in \eqref{lem:3.2:2}, we obtain
\begin{equation}\label{lem:3.2:4}
	\langle \nabla _yf(x_{k},y_{k-1})-\frac{1}{\rho}(y_k-y_{k-1}),y_{k+1}-y_k \rangle \le 0,
\end{equation}

Next, we estimate the three terms in the right hand side of \eqref{lem:3.2:6} respectively.
By Assumption \ref{sec:2:ass1:lip} and the Cauchy-Schwarz inequality, we can bound the first two terms according to
\begin{align}\label{lem:3.2:7}
	&\langle  \nabla _yf( x_{k+1},y_k ) -\nabla _yf\left( x_k,y_{k} \right) ,y_{k+1}-y_k \rangle  \nonumber\\
	\leq &\frac{L_{12}^{2}\rho}{2}\| x_{k+1}-x_k \|^2+\frac{1}{2\rho}\| y_{k+1}-y_k \|^2,
\end{align}
and
\begin{align}\label{lem:3.2:8}
	&\langle  \nabla _yf\left(  x_k,y_{k} \right) -\nabla _yf( x_k,y_{k-1}) ,v_{k+1} \rangle  \leq \frac{\rho L_{22}^{2}}{2}\|y_k-y_{k-1} \|^2+\frac{1}{2\rho}\|v_{k+1} \|^2.
\end{align}

For the third term, by $\mu $-strongly-concavity  of $f$ with respect to $y$,
\begin{align}\label{lem:3.2:9}
	\quad \langle  \nabla _yf\left( x_k,y_{k} \right) -\nabla _yf( x_k,y_{k-1}) ,y_k-y_{k-1} \rangle  \le -\mu \| y_k-y_{k-1} \|^2 .
\end{align}

Moreover, it can be easily checked that
\begin{align}\label{lem:3.2:10:3points}
	&\langle  y_k-y_{k-1},y_{k+1}-y_k \rangle =\frac{1}{2}\| y_k-y_{k-1} \|^2+\frac{1}{2}\| y_{k+1}-y_k \|^2-\frac{1}{2}\| v_{k+1} \|^2.
\end{align}

Plugging \eqref{lem:3.2:6}-\eqref{lem:3.2:10:3points} into \eqref{lem:3.2:5} and rearranging the terms, we conclude that
\begin{align}\label{lem:3.2:11}
	&f( x_{k+1},y_{k+1}) -f( x_{k+1},y_{k})  \nonumber \\
	\leq& \frac{L_{12}^{2}\rho}{2}\| x_{k+1}-x_k \|^2-(\mu-\frac{1}{2\rho}-\frac{\rho L_{22}^2}{2})\| y_k-y_{k-1}\|^2\nonumber\\
	&-(\frac{\mu}{2}-\frac{1}{\rho})\|y_{k+1}-y_k \|^2.
\end{align}

By setting $\beta_k=\eta$, $b_k=0$ in \eqref{lem:2.1:1} of Lemma \ref{lem:2.1}  and the assumption $\eta > L_{11}$, we have
		\begin{equation}\label{lem:3.1:1}
			f(x_{k+1},y_{k})-f(x_{k},y_k)\le -\frac{\eta}{2}\| x_{k+1}-x_k \|^2.
		\end{equation}

\begin{lem}\label{lem:4.2}
	Suppose that Assumption \ref{sec:2:ass1:lip} holds. Let $\{\left(x_{k},y_{k}\right)\}$ be a sequence generated by Algorithm \ref{alg:2.1}
	with parameter settings in \eqref{subsec:4.1:1:para}. If $\nu > L_{22}$, then we have
	\begin{align}\label{lem:4.2:1:conclu}
		&f( x_{k+1},y_{k+1}) -f( x_{k},y_{k})  \nonumber \\
		\geq& \frac{\nu}{2}\| y_{k+1}-y_{k} \| ^2-\frac{L_{21}^{2}\zeta}{2}\| y_{k}-y_{k-1} \|^2+(\theta-\frac{1}{2\zeta}-\frac{\zeta L_{11}^2}{2})\| x_{k}-x_{k-1}\|^2\nonumber\\
		&+ (\frac{\theta}{2}-\frac{1}{\zeta})\|x_{k+1}-x_{k} \|^2.
	\end{align}
\end{lem}

\begin{proof}
	Similar to \eqref{lem:3.2:2}-\eqref{lem:3.2:4} in the proof of Lemma \ref{lem:3.2:blostr:y}, by the optimality condition for $x_k$ in \eqref{subsec:4.1:2:x} implies that $\forall x\in \mathcal{X}$ and $\forall k\geq 1$,
	\begin{align}
		\langle \nabla _xf(x_{k},y_{k})+\frac{1}{\zeta}(x_{k+1}-x_{k}),x-x_{k+1} \rangle &\ge 0,\label{lem:4.2:2:opty}\\
		\langle \nabla _xf(x_{k},y_{k})+\frac{1}{\zeta}(x_{k+1}-x_{k}) ,x_{k}-x_{k+1} \rangle &\ge 0,\label{lem:4.2:3:nopty}\\
		\langle \nabla _xf(x_{k-1},y_{k-1})+\frac{1}{\zeta}(x_{k}-x_{k-1}),x_{k+1}-x_{k} \rangle &\ge 0,\label{lem:4.2:4:opty:k}
	\end{align}
which, in view of the fact that $f\left( x,y  \right)$ is $\theta $-strongly convex w.r.t. $x$ for any given $y\in \mathcal{Y}$,
	then implies that
	\begin{align}\label{lem:4.2:5}
		&f( x_{k+1},y_{k}) -f( x_{k},y_{k} ) \nonumber\\
		\geq &  \langle  \nabla _xf( x_{k},y_{k} ),x_{k+1}-x_{k}\rangle  +\frac{\theta}{2}\| x_{k+1}-x_{k} \|^2\  \nonumber\\
		\geq &\langle  \nabla _xf( x_{k},y_{k} ) -\nabla _xf( x_{k-1},y_{k-1}) ,x_{k+1}-x_{k} \rangle  \nonumber\\
		& -\frac{1}{\zeta}\langle  x_{k}-x_{k-1},x_{k+1}-x_{k} \rangle +\frac{\theta}{2}\| x_{k+1}-x_{k} \|^2.
	\end{align}
	Denoting $m_{k+1}:=\left(x_{k+1}-x_k\right)-\left(x_k-x_{k-1}\right)$, by Assumption \ref{sec:2:ass1:lip}, the Cauchy-Schwarz inequality and
	the $\theta $-strongly convexity  of $f$ w.r.t. $x$, we can estimate the first inner product term in the r.h.s.
	of \eqref{lem:4.2:5} as
	\begin{align}
		&\langle  \nabla _x f ( x_{k},y_{k} ) -\nabla _x f ( x_{k-1},y_{k-1}) ,x_{k+1}-x_{k} \rangle  \nonumber\\
		=&\langle  \nabla _x f ( x_{k},y_{k} ) -\nabla _x f \left( x_{k},y_{k-1} \right) ,x_{k+1}-x_{k} \rangle  \nonumber\\
		& + \langle  \nabla _x f \left( x_{k},y_{k-1} \right) -\nabla _x f ( x_{k-1},y_{k-1}) ,m_{k+1} \rangle  \nonumber\\
		&+\langle  \nabla _x f \left( x_{k},y_{k-1}\right) -\nabla _x f ( x_{k-1},y_{k-1}) ,x_{k}-x_{k-1} \rangle \label{lem:4.2:6}\\
	\geq &-\frac{L_{21}^{2}\zeta}{2}\| y_{k}-y_{k-1} \|^2-\frac{1}{2\zeta}\| x_{k+1}-x_k \|^2-\frac{\zeta L_{11}^{2}}{2}\|x_k-x_{k-1} \|^2\nonumber\\
	&-\frac{1}{2\zeta}\|m_{k+1} \|^2 +	\theta \| x_k-x_{k-1} \|^2.\label{lem:4.2:7}
	\end{align}
	Moreover, it can be easily checked that
\begin{align}\label{lem:4.2:8:3points}
		&\langle  x_k-x_{k-1},x_{k+1}-x_k \rangle =\frac{1}{2}\| x_k-x_{k-1} \|^2+\frac{1}{2}\| x_{k+1}-x_k \|^2-\frac{1}{2}\| m_{k+1} \|^2.
	\end{align}
	Plugging \eqref{lem:4.2:7} and \eqref{lem:4.2:8:3points} into \eqref{lem:4.2:5} and rearranging the terms, we conclude that
	\begin{align}\label{lem:4.2:9}
	f( x_{k+1},y_{k}) -f( x_{k},y_{k})	\geq& -\frac{L_{21}^{2}\zeta}{2}\| y_{k}-y_{k-1} \|^2+(\theta-\frac{1}{2\zeta}-\frac{\zeta L_{11}^2}{2})\| x_{k}-x_{k-1}\|^2\nonumber\\
		&+ (\frac{\theta}{2}-\frac{1}{\zeta})\|x_{k+1}-x_{k} \|^2.
	\end{align}
By setting $\gamma_k=\nu$, $c_k=0$ in \eqref{lem:2.1:2} of Lemma \ref{lem:2.1}  and the assumption $\nu > L_{22}$, we have
		\begin{equation}\label{lem:4.1:1:conclu}
			f( x_{k+1},y_{k+1}) -f( x_{k+1},y_k )\ge \frac{\nu}{2}\| y_{k+1}-y_k \|^2.
		\end{equation}
	The proof is completed by combining \eqref{lem:4.2:9} with \eqref{lem:4.1:1:conclu}.
\end{proof}

\begin{proof}
	Similar to \eqref{lem:3.2:2}-\eqref{lem:3.2:4} in the proof of Lemma \ref{lem:3.2:blostr:y}, by the optimality condition for $x_k$ in \eqref{subsec:4.1:2:x} implies that $\forall x\in \mathcal{X}$ and $\forall k\geq 1$,
	\begin{align}
