			f( x_{k+1},y_{k+1}) -f( x_{k+1},y_k )\ge \frac{\nu}{2}\| y_{k+1}-y_k \|^2.
		\end{equation}

\begin{lem}\label{lem:4.3}
	Suppose that Assumption \ref{sec:2:ass1:lip} holds. Let $\{\left(x_k,y_k\right)\}$ be a sequence generated by Algorithm \ref{alg:2.1}
	with parameter settings in \eqref{subsec:4.1:1:para}. Denote
	$$\hat{f}_{k+1}:=f\left( x_{k+1},y_{k+1} \right),\ \hat{S}_{k+1}:=-\frac{2}{\zeta^2\theta}\lVert x_{k+1}-x_k \rVert^2,$$
	$$\hat{F}_{k+1}:=\hat{f}_{k+1}+\hat{S}_{k+1}+ (\theta+\frac{7}{2\zeta}-\frac{\zeta L_{11}^2}{2}-\frac{2L_{11}^2}{\theta})\lVert x_{k+1}-x_{k} \rVert^2-(\frac{L_{21}^2\zeta}{2}+\frac{2L_{21}^2}{\theta^2\zeta})\|y_{k+1}-y_k\|^2.$$
	If $\nu>L_{22}$,
%	\begin{equation}\label{lem:4.3:1}
%, \nu>L_{21}^2\zeta+\frac{4L_{21}^2}{\zeta \theta^2},~\zeta\leq \frac{\theta}{4L_{11}^2},
%	\end{equation}
	then $\forall k \geq 1$,
	\begin{align}\label{lem:4.3:2:conclus}
		\hat{F}_{k+1}-\hat{F}_k\geq& \left(\frac{\nu}{2}-\frac{\zeta L_{21}^2}{2}-\frac{2L_{21}^2}{\zeta \theta^2}\right)\lVert y_{k+1}-y_k \rVert ^2\nonumber\\
		& +\left(\frac{3\theta-\zeta L_{11}^2}{2}+\frac{\theta-4\zeta L_{11}^2}{2\zeta\theta}\right)\lVert x_{k+1}-x_k \rVert ^2.
	\end{align}
\end{lem}

\begin{proof}
First by \eqref{lem:4.2:3:nopty} and \eqref{lem:4.2:4:opty:k}, we have
	\begin{align}\label{lem:4.3:3}
		\frac{1}{\zeta}\langle m_{k+1}, x_k -x_{k+1} \rangle
		\ge \langle \nabla _xf( x_k,y_k ) -\nabla _xf\left( x_{k-1},y_{k-1} \right),x_{k+1}-x_k \rangle,
	\end{align}
which together with \eqref{lem:4.2:6} then imply that
%	\eqref{lem:4.3:3} then implies that
	\begin{align}
		\frac{1}{\zeta}\langle m_{k+1},x_k-x_{k+1}  \rangle  \geq&\langle  \nabla _xf( x_{k},y_{k} ) -\nabla _xf\left( x_{k},y_{k-1} \right) ,x_{k+1}-x_{k} \rangle  \nonumber\\
		& + \langle  \nabla _xf\left( x_{k},y_{k-1} \right) -\nabla _xf\left( x_{k-1},y_{k-1} \right) ,m_{k+1} \rangle  \nonumber\\
		&+\langle  \nabla _xf\left( x_k,y_{k-1} \right) -\nabla _xf\left( x_{k-1},y_{k-1} \right) ,x_{k}-x_{k-1} \rangle \label{lem:4.3:4}\\
		\geq& -\frac{L_{21}^{2}}{2 \theta}\|y_{k}-y_{k-1} \|^2-\frac{\theta}{2}\|x_{k+1}-x_{k} \|^2-\frac{\zeta L_{11}^2}{2}\|x_{k}-x_{k-1} \|^2\nonumber\\
		&-\frac{1}{2\zeta}\| m_{k+1}\|^2+\theta\|x_{k}-x_{k-1} \|^2,\label{lem:4.3:5}
	\end{align}
where the second inequality is similar to the proof of \eqref{lem:4.2:7} except that for the first term in the r.h.s., we use $\langle  \nabla _xf( x_{k},y_{k} ) -\nabla _xf\left( x_{k},y_{k-1} \right) ,x_{k+1}-x_{k} \rangle \geq -\frac{L_{21}^{2}}{2 \theta}\|y_{k}-y_{k-1} \|^2-\frac{\theta}{2}\|x_{k+1}-x_k \|^2$. By using the identity $\frac{1}{\zeta}\langle m_{k+1},x_{k}-x_{k+1} \rangle  =\frac{1}{2\zeta}\|x_{k}-x_{k-1}\|^2- \frac{1}{2\zeta}\|x_{k+1}-x_{k}\|^2-\frac{1}{2\zeta}\| m_{k+1}\| ^2$, we conclude from \eqref{lem:4.3:5} that
	\begin{align}\label{lem:4.3:6}
		&\frac{1}{2\zeta}\|x_{k}-x_{k-1}\|^2- \frac{1}{2\zeta}\|x_{k+1}-x_{k}\|^2-\frac{1}{2\zeta}\| m_{k+1}\| ^2\nonumber\\
		\geq& -\frac{L_{21}^{2}}{2 \theta}\|y_{k}-y_{k-1} \|^2-\frac{\theta}{2}\|x_{k+1}-x_k \|^2-\frac{\zeta L_{11}^2}{2}\|x_{k}-x_{k-1} \|^2\nonumber\\
		&-\frac{1}{2\zeta}\| m_{k+1}\|^2+\theta\|x_{k}-x_{k-1} \|^2.
	\end{align}
	Rearranging the terms of \eqref{lem:4.3:6}, we have
	\begin{align}\label{lem:4.3:7}
		&\frac{1}{2\zeta}\|x_{k}-x_{k-1}\|^2- \frac{1}{2\zeta}\|x_{k+1}-x_{k}\|^2\nonumber\\
		\geq& -\frac{L_{21}^{2}}{2 \theta}\|y_{k}-y_{k-1} \|^2-\frac{\theta}{2}\|x_{k+1}-x_{k} \|^2+\left(\theta-\frac{\zeta L_{11}^2}{2}\right)\|x_{k}-x_{k-1} \|^2.
	\end{align}
	Multiplying $\frac{4}{\zeta\theta}$ on both sides of \eqref{lem:4.3:7} and using the definition of $\hat{S}_{k+1}$, we obtain
	\begin{align*}
		\hat{S}_{k+1}-\hat{S}_k \geq & -\frac{2L_{21}^{2}}{\theta^2\zeta}\| y_{k}-y_{k-1}\|^2-\frac{2}{\zeta}\| x_{k+1}-x_k \|^2+\left(\frac{4}{\zeta}-\frac{2 L_{11}^2}{\theta}\right)\|x_{k}-x_{k-1} \|^2.
	\end{align*}
	The proof is completed by \eqref{lem:4.2:1:conclu} in Lemma \ref{lem:4.2} and the definition of $\hat{F}_k$.
\end{proof}

