Rearranging the terms of \eqref{lem:4.3:6}, we have
\begin{align}\label{lem:4.3:7}
	&\frac{1}{2\zeta}\|x_{k}-x_{k-1}\|^2- \frac{1}{2\zeta}\|x_{k+1}-x_{k}\|^2\nonumber\\
	\geq& -\frac{L_{21}^{2}}{2 \theta}\|y_{k}-y_{k-1} \|^2-\frac{\theta}{2}\|x_{k+1}-x_{k} \|^2+\left(\theta-\frac{\zeta L_{11}^2}{2}\right)\|x_{k}-x_{k-1} \|^2.
\end{align}

Multiplying $\frac{4}{\zeta\theta}$ on both sides of \eqref{lem:4.3:7} and using the definition of $\hat{S}_{k+1}$, we obtain
\begin{align*}
	\hat{S}_{k+1}-\hat{S}_k \geq & -\frac{2L_{21}^{2}}{\theta^2\zeta}\| y_{k}-y_{k-1}\|^2-\frac{2}{\zeta}\| x_{k+1}-x_k \|^2+\left(\frac{4}{\zeta}-\frac{2 L_{11}^2}{\theta}\right)\|x_{k}-x_{k-1} \|^2.
\end{align*}

\begin{thm}\label{thm:4.1}
	Suppose that Assumption \ref{sec:2:ass1:lip} holds. Let $\{\left(x_{k},y_{k}\right)\}$ be a sequence generated by Algorithm \ref{alg:2.1}
	with parameter settings in \eqref{subsec:4.1:1:para}.
	If the relations $\nu>L_{22}, \nu>L_{21}^2\zeta+\frac{4L_{21}^2}{\zeta \theta^2},~\zeta\leq \frac{\theta}{4L_{11}^2}$ are satisfied, then $\forall \varepsilon>0$,  it holds that $$ T\left( \varepsilon \right) \le
	\tfrac{\overline{F}-\hat{F}_1}{\hat{d}_1\varepsilon ^2},$$
	where
	$\hat{d}_1:=\tfrac{\min \left\{\tfrac{\nu}{2}-\tfrac{\zeta L_{21}^2}{2}-\tfrac{2 L_{21}^2}{\zeta \theta^2},\tfrac{3\theta-\zeta L_{11}^2}{2}+\tfrac{\theta-4\zeta L_{11}^2}{2\zeta\theta} \right\}}{\max \left\{ \tfrac{1}{\zeta ^2}+2L_{12}^{2},2\nu^2 \right\}}%\overline{\hat{F}}=\overline{f}-(\tfrac{\theta}{2}-\tfrac{3}{\zeta})\sigma _x^2
	$
	and $\overline{F}=\bar{f}+(\theta+\frac{7}{2\zeta}-\frac{\zeta L_{11}^2}{2}-\frac{2L_{11}^2}{\theta})\sigma_x^2$ with $\overline{f} := \max_{(x,y) \in \mathcal{X} \times \mathcal{Y}} f(x,y)$ and $\sigma _x= \max\{\|x_1-x_2\| \mid \forall x_1, x_2\in \mathcal{X}\}$.
\end{thm}

\begin{proof}
	By \eqref{subsec:4.1:2:x}, we immediately obtain
	\begin{equation}
		\|(\nabla G_k)_{x} \|\leq\frac{1}{\zeta}\| x_{k+1}-x_{k} \|.\label{thm:4.1:1:gx}
	\end{equation}
	On the other hand, similar to the proof of \eqref{thm:3.1:2:gy},  by \eqref{subsec:4.1:3:y} and the triangle inequality, and the nonexpansiveness of the projection operator $\operatorname{ \mathcal{P}_\mathcal{Y}}$, we conclude that
	\begin{align}\label{thm:4.1:2:gy}
		\| (\nabla G_k)_{y} \|\le& \nu\| y_{k+1}-y_k \|+L_{12}\|x_{k+1}-x_{k} \|.
			\end{align}
%		\leq&\nu\|\operatorname{ Prox_{\mathcal{Y}_j}^{\nu}}\left( y_j^r+\frac{1}{\nu} \nabla _{y_j}f\left( x^{r+1} ,w_j^{r+1} \right) \right)-\operatorname{ Prox_{\mathcal{Y}_j}^{\nu}}\left( y_j^r+ \frac{1}{\nu} \nabla _{y_j}f\left( x^r,y^r \right) \right) \|\nonumber\\
%		&+\nu\| y_j^{r+1}-y_j^r \|\nonumber\\
%		\leq& \nu\| y_j^{r+1}-y_j^r \| +\|\nabla _{y_j}f\left( x^{r+1} ,w_j^{r+1} \right)-\nabla _{y_j}f\left( x^r,y^r \right) \|\nonumber\\
%		\leq & \nu\| y_j^{r+1}-y_j^r \| +\|\nabla _{y_j}f\left( x^{r+1} ,w_j^{r+1} \right)-\nabla _{y_j}f\left( x^r,w_j^{r+1} \right) \|\nonumber\\
%		& +\|\nabla _{y_j}f\left( x^r ,w_j^{r+1} \right)-\nabla _{y_j}f\left( x^r,y^r \right) \|\nonumber\\
%		\le& \nu\| y_j^{r+1}-y_j^r \|+L_{12}\|x^{r+1}-x^r \|+L_{22}\|w_j^{r+1}-y^r \|\nonumber\\
%	where the second inequality holds by the nonexpansiveness of the proximal operator $\operatorname{ Prox_{\mathcal{Y}_j}^{\nu}}$, the last inequality holds since that $\| y_i^{r+1}-y_i^r \|\le\| y^{r+1}-y^r \|$ and $\|w_j^{r+1}-y^r \|\le\| y^{r+1}-y^r \|$ by the definition of $y_j$ and $w_j^{r+1}$.
	By combining \eqref{thm:4.1:1:gx} and \eqref{thm:4.1:2:gy}, and using the Cauchy-Schwarz inequality, we obtain
	\begin{align}\label{thm:4.1:3:g}
		\| \nabla G_k \|^2
		\leq 2\nu^2\| y_{k+1}-y_{k} \|^2+\left( \frac{1}{\zeta ^2}+2L_{12}^{2} \right)\|x_{k+1}-x_{k} \|^2.
	\end{align}
	Observing that $\hat{d}_1 > 0$. Multiplying both sides of \eqref{thm:4.1:3:g} by $\hat{d}_1$, and using \eqref{lem:4.3:2:conclus} in Lemma \ref{lem:4.3},
	we have
	\begin{align}\label{thm:4.1:4:d1}
		\hat{d}_1\|\nabla G_k \|^2\le \hat{F}_{k+1}-\hat{F}_k.
	\end{align}
	Summing up the above inequalities from $k=1$ to $k=T(\varepsilon)$, we obtain
	\begin{align}\label{thm:4.1:5}
		\sum_{k=1}^{T\left( \varepsilon \right)}{\hat{d}_1\|\nabla G_k \| ^2}\le \hat{F}_{T\left( \varepsilon \right)+1}-\hat{F}_1.
	\end{align}
	Note that by the definition of $\hat{F}_{k+1}$ in Lemma \ref{lem:4.3}, we have
	\begin{align*}
		\hat{F}_{T\left( \varepsilon \right)+1}&\le
		\hat{f}_{T\left( \varepsilon \right)+1}+(\theta+\frac{7}{2\zeta}-\frac{\zeta L_{11}^2}{2}-\frac{2L_{11}^2}{\theta})\|x_{T\left( \varepsilon \right)+1}-x_{T\left( \varepsilon \right)} \|^2\\
		&\le \bar{f}+(\theta+\frac{7}{2\zeta}-\frac{\zeta L_{11}^2}{2}-\frac{2L_{11}^2}{\theta})\sigma_x^2 = \bar{F},
	\end{align*}
	where the last inequality follows from the definitions of $\bar{f}$ and  $\sigma _x$, and $\theta+\frac{7}{2\zeta}-\frac{\zeta L_{11}^2}{2}-\frac{2L_{11}^2}{\theta} \ge 0 $ due to
	the selection of $\zeta$.
	We then conclude from \eqref{thm:4.1:5} that $\sum_{k=1}^{T\left( \varepsilon \right)}{\hat{d}_1\| \nabla G_k \|^2}\le \bar{F}-\hat{F}_1$ which, in view of the definition of $T(\varepsilon)$, implies that $\varepsilon ^2\le (\bar{F}-\hat{F}_1)/(T( \varepsilon )\cdot \hat{d}_1)$
	or equivalently, $T\left( \varepsilon \right) \le (\bar{F}-\hat{F}_1)/(\hat{d}_1\varepsilon ^2)$.
\end{proof}

